replacements.before:
aside .brand {
  height: 60px;
  padding: 0 20px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 17px;
  font-weight: 700;
  color: #ffffff;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

replacements.after:
aside .brand {
  flex-shrink: 0;
  height: 60px;
  padding: 0 20px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 17px;
  font-weight: 700;
  color: #ffffff;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

replacements.before:
nav#nav {
  flex: 1;
  padding: 14px 10px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

nav#nav button,
nav#nav a {
  all: unset;
  display: flex;
  align-items: center;
  height: 40px;
  padding: 0 12px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 500;
  color: #94a3b8;
  cursor: pointer;
  box-sizing: border-box;
  transition: color 0.15s ease, background 0.15s ease;
}

nav#nav button:hover,
nav#nav a:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #ffffff;
}

nav#nav button.active,
nav#nav a.active,
nav#nav button[aria-current="page"],
nav#nav a[aria-current="page"] {
  background: var(--teal-primary);
  color: #ffffff;
  font-weight: 600;
}

aside .asidefoot {
  padding: 14px 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  font-size: 13px;
  color: #64748b;
}

replacements.after:
nav#nav {
  flex: 1 1 auto;
  min-height: 0;
  padding: 14px 10px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

nav#nav button,
nav#nav a {
  all: unset;
  display: flex;
  align-items: center;
  flex-shrink: 0;
  height: 40px;
  padding: 0 12px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 500;
  color: #94a3b8;
  cursor: pointer;
  box-sizing: border-box;
  transition: color 0.15s ease, background 0.15s ease;
}

nav#nav button:focus-visible,
nav#nav a:focus-visible {
  outline: 2px solid var(--teal-primary);
  outline-offset: 1px;
}

nav#nav button:hover,
nav#nav a:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #ffffff;
}

nav#nav button.active,
nav#nav a.active,
nav#nav button[aria-current="page"],
nav#nav a[aria-current="page"] {
  background: var(--teal-primary);
  color: #ffffff;
  font-weight: 600;
}

aside .asidefoot {
  position: static;
  left: auto;
  bottom: auto;
  flex-shrink: 0;
  padding: 14px 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  font-size: 13px;
  color: #94a3b8;
}
